
import json
import csv
from kafka import KafkaProducer

# Connect to Kafka
producer = KafkaProducer(
    bootstrap_servers="localhost:9092",
    value_serializer=lambda v: json.dumps(v).encode("utf-8")
)

# Read sensor data generated by main.py
with open("sensor_readings.csv", "r") as file:
    reader = csv.DictReader(file)

    count = 0

    for row in reader:
        # Convert sensor values into numeric data
        row["temperature_c"] = float(row["temperature_c"])
        row["humidity_percent"] = float(row["humidity_percent"])
        row["vibration_mm_s"] = float(row["vibration_mm_s"])

        producer.send("sensor_readings", value=row)
        count += 1

producer.flush()
producer.close()

print(f"Successfully sent {count} sensor readings to Kafka!")
